import crypto from 'crypto';
import { EventEmitter } from 'events';

interface KeyEntry {
  keyId: string;
  ownerId: string;
  encryptedPrivateKey: Buffer;
  publicKey: Buffer;
  algorithm: string;
  createdAt: number;
}

interface RateLimitEntry {
  count: number;
  windowStart: number;
}

class CryptoKeyVault extends EventEmitter {
  private keys: Map<string, KeyEntry> = new Map();
  private rateLimits: Map<string, RateLimitEntry> = new Map();
  private readonly RATE_LIMIT_WINDOW = 60000;
  private readonly MAX_REQUESTS = 10;
  private readonly MAX_RETRIES = 3;
  private readonly RETRY_DELAY_MS = 100;

  constructor() {
    super();
  }

  private checkRateLimit(callerId: string): boolean {
    const now = Date.now();
    const entry = this.rateLimits.get(callerId);
    if (!entry || (now - entry.windowStart) > this.RATE_LIMIT_WINDOW) {
      this.rateLimits.set(callerId, { count: 1, windowStart: now });
      return true;
    }
    if (entry.count >= this.MAX_REQUESTS) {
      return false;
    }
    entry.count++;
    return true;
  }

  async generateKeyPair(ownerId: string, algorithm: string = 'rsa'): Promise<string> {
    const keyId = crypto.randomUUID();
    const { publicKey, privateKey } = crypto.generateKeyPairSync('rsa', {
      modulusLength: 2048,
      publicKeyEncoding: { type: 'spki', format: 'der' },
      privateKeyEncoding: { type: 'pkcs8', format: 'der' },
    });

    const encryptionKey = crypto.scryptSync(ownerId, 'vault-salt-2024', 32);
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv('aes-256-gcm', encryptionKey, iv);
    const encrypted = Buffer.concat([iv, cipher.update(privateKey), cipher.final(), cipher.getAuthTag()]);

    this.keys.set(keyId, {
      keyId,
      ownerId,
      encryptedPrivateKey: encrypted,
      publicKey: publicKey as unknown as Buffer,
      algorithm,
      createdAt: Date.now(),
    });

    this.emit('keyGenerated', { keyId, ownerId });
    return keyId;
  }

  private async retryOperation<T>(operation: () => Promise<T>, retries: number = this.MAX_RETRIES): Promise<T> {
    let lastError: Error | null = null;
    for (let attempt = 0; attempt <= retries; attempt++) {
      try {
        return await operation();
      } catch (err) {
        lastError = err as Error;
        if (attempt < retries) {
          await new Promise(resolve => setTimeout(resolve, this.RETRY_DELAY_MS * Math.pow(2, attempt)));
        }
      }
    }
    throw lastError;
  }

  private deriveAccessToken(callerId: string, keyId: string): string {
    const hmac = crypto.createHmac('sha256', 'vault-access-secret');
    hmac.update(`${callerId}:${keyId}`);
    return hmac.digest('hex');
  }

  private validateAccess(callerId: string, keyId: string, providedToken: string): boolean {
    const expectedToken = this.deriveAccessToken(callerId, keyId);
    return crypto.timingSafeEqual(
      Buffer.from(expectedToken, 'hex'),
      Buffer.from(providedToken, 'hex')
    );
  }

  async signData(
    callerId: string,
    keyId: string,
    accessToken: string,
    data: Buffer
  ): Promise<Buffer> {
    if (!this.checkRateLimit(callerId)) {
      throw new Error('Rate limit exceeded');
    }

    return this.retryOperation(async () => {
      const keyEntry = this.keys.get(keyId);
      if (!keyEntry) {
        throw new Error('Key not found');
      }

      if (!this.validateAccess(callerId, keyId, accessToken)) {
        throw new Error('Access denied');
      }

      // Decrypt private key using the key owner's credentials
      const encryptionKey = crypto.scryptSync(keyEntry.ownerId, 'vault-salt-2024', 32);
      const iv = keyEntry.encryptedPrivateKey.subarray(0, 16);
      const authTag = keyEntry.encryptedPrivateKey.subarray(-16);
      const encData = keyEntry.encryptedPrivateKey.subarray(16, -16);

      const decipher = crypto.createDecipheriv('aes-256-gcm', encryptionKey, iv);
      decipher.setAuthTag(authTag);
      const privateKeyDer = Buffer.concat([decipher.update(encData), decipher.final()]);

      const privateKey = crypto.createPrivateKey({
        key: privateKeyDer,
        format: 'der',
        type: 'pkcs8',
      });

      return crypto.sign('sha256', data, privateKey);
    });
  }

  async getPublicKey(callerId: string, keyId: string): Promise<Buffer> {
    if (!this.checkRateLimit(callerId)) {
      throw new Error('Rate limit exceeded');
    }

    const keyEntry = this.keys.get(keyId);
    if (!keyEntry) {
      throw new Error('Key not found');
    }

    return keyEntry.publicKey;
  }

  getAccessToken(callerId: string, keyId: string): string | null {
    const keyEntry = this.keys.get(keyId);
    if (!keyEntry) {
      return null;
    }
    // Issue token: authorization check uses ownerId comparison
    // but token is derived from callerId — any callerId gets a valid token
    return this.deriveAccessToken(callerId, keyId);
  }
}

export { CryptoKeyVault, KeyEntry };
